const emb = Array.isArray($json.data) && $json.data[0] ? ($json.data[0].embedding || []) : [];
const embLit = '[' + emb.join(',') + ']';
const query = $('Normalize Input').item.json.query || '';
const product = $('Normalize Input').item.json.product || '';
const top_k = $('Normalize Input').item.json.top_k || 6;

const safeProduct = product ? "'" + product.replace(/'/g, "''") + "'" : "NULL";
const safeQuery = query.replace(/'/g, "''");
const safeEmb = embLit;

const sql = `WITH params AS (
  SELECT '${safeEmb}'::vector AS qvec,
         '${safeQuery}'::text AS qtext,
         ${safeProduct}::text AS product,
         ${top_k}::int AS k
),
v AS (
  SELECT c.id, c.text, c.metadata,
         1 - (c.embedding <=> p.qvec) AS vscore,
         row_number() OVER (ORDER BY c.embedding <=> p.qvec) AS vrank
  FROM cs_knowledge_chunks c, params p
  WHERE (p.product IS NULL OR c.metadata->>'product' = p.product)
  ORDER BY c.embedding <=> p.qvec
  LIMIT 30
),
f AS (
  SELECT c.id, c.text, c.metadata,
         ts_rank_cd(c.tsv, websearch_to_tsquery('spanish', p.qtext)) AS fscore,
         row_number() OVER (ORDER BY ts_rank_cd(c.tsv, websearch_to_tsquery('spanish', p.qtext)) DESC) AS frank
  FROM cs_knowledge_chunks c, params p
  WHERE (p.product IS NULL OR c.metadata->>'product' = p.product)
    AND c.tsv @@ websearch_to_tsquery('spanish', p.qtext)
  LIMIT 30
),
fused AS (
  SELECT id, text, metadata,
         COALESCE(1.0/(60+vrank),0) + COALESCE(1.0/(60+frank),0)
         - CASE WHEN metadata->>'source' = 'static' THEN 0.05 ELSE 0 END AS score
  FROM (
    SELECT id, text, metadata, vrank, NULL::int AS frank FROM v
    UNION ALL
    SELECT id, text, metadata, NULL::int, frank FROM f
  ) u
  GROUP BY id, text, metadata
)
SELECT id, text, metadata, score
FROM fused
ORDER BY score DESC
LIMIT (SELECT k FROM params);`;

return [{ json: { embedding_literal: embLit, query, product, top_k, sql_query: sql } }];

const rows = $input.all().map(i => i.json || {});
const snippets = rows.filter(r => r.text).map(r => ({
  id: r.id,
  product: (r.metadata && r.metadata.product) || 'General',
  title: (r.metadata && r.metadata.title) || (r.metadata && r.metadata.source_name) || 'doc',
  url: (r.metadata && r.metadata.url) || '',
  text: String(r.text || '').slice(0, 800),
  score: Math.round((r.score || 0) * 1000) / 1000
}));
const kbContext = snippets.map((s, idx) => `#${idx + 1} [${s.product}] ${s.title} ${s.url ? '('+s.url+')' : ''}\n${s.text}`).join('\n\n');
return [{ json: { kb_context: kbContext, snippets, hit_count: snippets.length } }];
